if(class_exists('AccessManager'))AccessManager::requirePageAccess('planning_chantier/dashboard.php');
$userId=(int)(planning_chantier_user_id()??0);$service=new MeetingDailyFollowupService($pdo);
$_SESSION['meeting_tracking_csrf']??=bin2hex(random_bytes(24));
if(($_SERVER['REQUEST_METHOD']??'GET')==='POST'){
    try{
        if(!hash_equals((string)$_SESSION['meeting_tracking_csrf'],(string)($_POST['_csrf']??'')))throw new RuntimeException('Session expirée. Rechargez la page.');
        $keys=array_values(array_unique(array_filter((array)($_POST['keys']??[]))));$action=(string)($_POST['bulk_action']??'remind');
        if(in_array($action,['export_pdf','export_excel'],true)){if(!$keys)throw new RuntimeException('Sélectionnez au moins un engagement.');$_SESSION['meeting_followup_export_keys']=$keys;header('Location: request/export_followups_'.($action==='export_pdf'?'pdf':'excel').'.php');exit;}
        if($action==='tickets'){$result=$service->createTickets($keys,$userId,(string)($_SESSION['user_name']??'Utilisateur Finéa'));pc_flash_set('success',$result['created'].' ticket(s) créé(s). '.$result['existing'].' existaient déjà.');}
        else{$result=$service->bulkReminder($keys,$userId,(string)($_POST['note']??''),!empty($_POST['send_email']),(array)($_POST['cc_ids']??[]));pc_flash_set('success',$result['reminders'].' relance(s) enregistrée(s)'.($result['emails']?' et '.$result['emails'].' e-mail(s) envoyé(s)':'').'.');}
    }catch(Throwable $e){pc_flash_set('error',$e->getMessage());}
    header('Location: meeting_followups.php'.(!empty($_POST['return_query'])?'?'.ltrim((string)$_POST['return_query'],'?&'):''));exit;
}
$rows=$service->trackingRows();$status=(string)($_GET['status']??'all');$persons=array_values(array_unique(array_map('intval',(array)($_GET['persons']??[]))));$scopesSelected=array_values(array_unique(array_map('strval',(array)($_GET['scopes']??[]))));$type=(string)($_GET['type']??'all');$search=mb_strtolower(trim((string)($_GET['q']??'')));
$people=[];$services=[];$scopes=[];$stats=['open'=>0,'late'=>0,'deferred'=>0,'completed'=>0];
foreach($rows as &$row){
    $people[(int)$row['user_id']]=$row['user_name']?:('Utilisateur #'.$row['user_id']);
    if((int)$row['office_ligne_devis_id']>0){$services[(string)$row['service_label']]=(string)$row['service_label'];$scopeKey='office:'.(int)$row['office_ligne_devis_id'];$scopes[$scopeKey]='Bureau · '.(string)$row['service_label'];}else{$scopeKey='site:'.(int)$row['chantier_id'];$scopes[$scopeKey]='Chantier · '.trim((string)$row['chantier_code'].' · '.(string)$row['chantier_label'],' ·');}$row['_scope_key']=$scopeKey;
    $due=(string)($row['execution_date']?:($row['new_deadline']?:$row['old_deadline']));
    $row['_status']=!empty($row['completed_at'])?'completed':((string)$row['response_type']==='decision_deferred'?'deferred':($due!==''&&$due<date('Y-m-d')?'late':'open'));
}unset($row);asort($people,SORT_NATURAL|SORT_FLAG_CASE);asort($services,SORT_NATURAL|SORT_FLAG_CASE);asort($scopes,SORT_NATURAL|SORT_FLAG_CASE);
$contextRows=array_values(array_filter($rows,static function(array $r)use($persons,$scopesSelected,$type,$search):bool{
    if($persons&&!in_array((int)$r['user_id'],$persons,true))return false;
    if($scopesSelected&&!in_array((string)$r['_scope_key'],$scopesSelected,true))return false;
    if($type==='office'&&(int)$r['office_ligne_devis_id']<=0)return false;if($type==='site'&&(int)$r['office_ligne_devis_id']>0)return false;
    if($search!==''&&!str_contains(mb_strtolower(implode(' ',[(string)$r['user_name'],(string)$r['section_title'],(string)$r['task_title'],(string)$r['checklist_label'],(string)$r['service_label'],(string)$r['chantier_label']])), $search))return false;return true;
}));foreach($contextRows as $row)$stats[$row['_status']]++;$filtered=$status===''||$status==='all'?$contextRows:array_values(array_filter($contextRows,static fn(array $r):bool=>$r['_status']===$status));$staff=$service->personnel();$filteredOffice=count(array_filter($filtered,static fn(array $r):bool=>(int)$r['office_ligne_devis_id']>0));$filteredSite=count($filtered)-$filteredOffice;$cardQuery=$_GET;unset($cardQuery['service']);
$pageTitle='Suivi des engagements de réunion';$activeMenu='planning_chantier';
if(!planning_chantier_include_layout('header'))pc_render_fallback_header($pageTitle);planning_chantier_include_layout('navbar');
pc_render_page_start('Suivi des engagements','Consultez les réponses partielles, les reports, les retards et relancez directement le pilote ou le copilote.','Pilotage des décisions');
