<script>
document.addEventListener('DOMContentLoaded',()=>{
  document.querySelectorAll('[data-smart-multi]').forEach(root=>{
    const input=root.querySelector('.mf-multi-search'),tags=root.querySelector('[data-tags]'),options=[...root.querySelectorAll('.mf-option')],empty=root.querySelector('.mf-empty'),name=root.dataset.name;
    const selected=()=>options.filter(o=>o.classList.contains('is-selected'));
    const render=()=>{tags.innerHTML='';root.querySelectorAll('input[type=hidden]').forEach(x=>x.remove());selected().forEach(option=>{const tag=document.createElement('span');tag.className='mf-tag';tag.innerHTML='<span></span><button type="button" aria-label="Retirer"><i class="fas fa-xmark"></i></button>';tag.querySelector('span').textContent=option.dataset.label;tag.querySelector('button').onclick=e=>{e.stopPropagation();option.classList.remove('is-selected');render()};tags.appendChild(tag);const hidden=document.createElement('input');hidden.type='hidden';hidden.name=name;hidden.value=option.dataset.value;root.appendChild(hidden)});const placeholders={'persons[]':'Rechercher des personnes…','scopes[]':'Rechercher un bureau ou un chantier…','cc_ids[]':'Ajouter des personnes en copie…'};input.placeholder=selected().length?'Ajouter…':(placeholders[name]||'Rechercher…')};
    const filter=()=>{const q=input.value.trim().toLowerCase();let visible=0;options.forEach(o=>{o.hidden=!o.dataset.label.toLowerCase().includes(q);if(!o.hidden)visible++});empty.style.display=visible?'none':'block'};
    root.querySelector('.mf-multi-control').onclick=()=>{root.classList.add('is-open');input.focus()};root.querySelector('.mf-multi-toggle').onclick=e=>{e.stopPropagation();root.classList.toggle('is-open');input.focus()};input.onfocus=()=>root.classList.add('is-open');input.oninput=filter;options.forEach(o=>o.onclick=()=>{o.classList.toggle('is-selected');input.value='';filter();render();input.focus()});render();
  });
  document.addEventListener('click',e=>document.querySelectorAll('[data-smart-multi].is-open').forEach(root=>{if(!root.contains(e.target))root.classList.remove('is-open')}));
  const keys=[...document.querySelectorAll('.followup-key')],count=document.querySelector('[data-selected-count]'),all=document.querySelector('[data-select-all]');const sync=()=>{const n=keys.filter(x=>x.checked).length;count.textContent=n+' sélectionné(s)';if(all){all.checked=n>0&&n===keys.length;all.indeterminate=n>0&&n<keys.length}};keys.forEach(x=>x.addEventListener('change',sync));if(all)all.onchange=()=>{keys.forEach(x=>x.checked=all.checked);sync()};document.querySelector('[data-select-results]')?.addEventListener('click',()=>{keys.forEach(x=>x.checked=true);sync()});document.querySelector('[data-email-toggle]')?.addEventListener('change',e=>document.querySelector('[data-email-options]').classList.toggle('hidden',!e.target.checked));document.querySelectorAll('[data-confirm]').forEach(b=>b.addEventListener('click',e=>{if(!keys.some(x=>x.checked)||!confirm(b.dataset.confirm)){e.preventDefault();if(!keys.some(x=>x.checked))alert('Sélectionnez au moins un engagement.')}}));
});
</script>
